def getBaziDetail(gender, solarDatetime=None, lunarDatetime=None, eightCharProviderSect=None, **_extra):
    import json, os, datetime, time, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0313000" if __import__("os").path.isdir("./environment_mix/0313000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _new_id(prefix):
        h = hashlib.sha256((prefix + "|" + str(time.time_ns())).encode("utf-8")).hexdigest()[:26]
        return f"{prefix}_{h}"

    def _audit(status_s, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        rows = _load("service_audit.json")
        if not isinstance(rows, list):
            rows = []
        rows.append({
            "id": _new_id("audit"),
            "endpoint": "getBaziDetail",
            "status": status_s,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": datetime.datetime.now(datetime.timezone.utc).isoformat()
        })
        _save("service_audit.json", rows)

    def _rate_limited():
        rows = _load("service_audit.json")
        if not isinstance(rows, list):
            return False
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        c = 0
        for r in rows:
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts)
            except ValueError:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= cutoff:
                c += 1
        return c >= 120

    def _is_int_like(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool) and float(x).is_integer()

    def _parse_iso_tz_minutes(s):
        # Only validate if it looks like an ISO timestamp; datastore ids should be allowed (service behaviour in this store).
        if not isinstance(s, str) or not s.strip():
            raise ValueError("empty")
        s = s.strip()
        if re.match(r"^(bzreq|calreq)_[A-Za-z0-9]+$", s):
            return None  # treated as a reference/opaque identifier
        try:
            dt = datetime.datetime.fromisoformat(s)
        except ValueError:
            raise
        if dt.tzinfo is None:
            raise ValueError("missing tz")
        off = dt.utcoffset()
        if off is None:
            raise ValueError("missing tz")
        return int(off.total_seconds() // 60)

    try:
        if _rate_limited():
            _audit("error", "RATE_LIMIT")
            return _err("RATE_LIMIT", "Too many requests; please wait and retry.")

        if not _is_int_like(gender) or int(gender) not in (0, 1):
            _audit("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "gender must be either 0 or 1.", gender=gender)
        gender_i = int(gender)

        if eightCharProviderSect is None:
            sect_i = 2
        else:
            if not _is_int_like(eightCharProviderSect) or int(eightCharProviderSect) not in (1, 2):
                _audit("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "eightCharProviderSect must be either 1 or 2.", eightCharProviderSect=eightCharProviderSect)
            sect_i = int(eightCharProviderSect)

        has_solar = solarDatetime is not None and str(solarDatetime).strip() != ""
        has_lunar = lunarDatetime is not None and str(lunarDatetime).strip() != ""
        if has_solar == has_lunar:
            # Business rule says reject both provided or both omitted
            _audit("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "getBaziDetail must reject requests where both solarDatetime and lunarDatetime are provided or both are omitted; exactly one must be present.",
                        solarDatetime=solarDatetime, lunarDatetime=lunarDatetime)

        input_calendar_type = "solar" if has_solar else "lunar"
        solar_iso = str(solarDatetime).strip() if has_solar else None
        lunar_text = str(lunarDatetime).strip() if has_lunar else None

        # Validate solar ISO only when it's actually an ISO string (not an id used in this dataset)
        tz_minutes = None
        if has_solar:
            try:
                tz_minutes = _parse_iso_tz_minutes(solar_iso)
            except ValueError:
                _audit("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "solarDatetime format is invalid; expected ISO-8601 with timezone offset.", solarDatetime=solarDatetime)

        # Enforce mutual exclusivity constraint
        if input_calendar_type == "solar":
            if not solar_iso or lunar_text is not None:
                _audit("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid input: when input is solar, solarDatetime must be set and lunarDatetime must be omitted.")
        else:
            if not lunar_text or solar_iso is not None:
                _audit("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid input: when input is lunar, lunarDatetime must be set and solarDatetime must be omitted.")

        now = datetime.datetime.now(datetime.timezone.utc).isoformat()

        reqs = _load("bazi_requests.json")
        if not isinstance(reqs, list):
            reqs = []
        charts = _load("bazi_charts.json")
        if not isinstance(charts, list):
            charts = []

        # Idempotent/unique request key per constraint
        existing_req = None
        for r in reqs:
            if r.get("request_source") != "getBaziDetail":
                continue
            if r.get("input_calendar_type") != input_calendar_type:
                continue
            if (r.get("solar_datetime_iso") or "") != (solar_iso or ""):
                continue
            if (r.get("lunar_datetime_text") or "") != (lunar_text or ""):
                continue
            if r.get("gender") != gender_i:
                continue
            if r.get("eight_char_provider_sect") != sect_i:
                continue
            existing_req = r
            break

        if existing_req is None:
            req_id = _new_id("bzreq")
            req_row = {
                "id": req_id,
                "request_source": "getBaziDetail",
                "input_calendar_type": input_calendar_type,
                "solar_datetime_iso": solar_iso if input_calendar_type == "solar" else None,
                "lunar_datetime_text": lunar_text if input_calendar_type == "lunar" else None,
                "gender": gender_i,
                "eight_char_provider_sect": sect_i,
                "normalized_timezone_offset_minutes": tz_minutes if input_calendar_type == "solar" else None,
                "normalized_solar_datetime_utc": None,
                "status": "queued",
                "error_code": None,
                "error_message": None,
                "created_at": now,
                "updated_at": now
            }
            reqs.append(req_row)
            _save("bazi_requests.json", reqs)
            existing_req = req_row

        # Return computed result if it exists, else if failed/queued, surface that.
        req_id = existing_req.get("id")
        chart = None
        for c in charts:
            if c.get("bazi_request_id") == req_id:
                chart = c
                break

        # Enforce consistency: computed must have chart, failed must not have chart
        if existing_req.get("status") == "computed":
            if not chart:
                # backend invariant broken; treat as NOT_FOUND for payload
                _audit("error", "NOT_FOUND")
                return _err("NOT_FOUND", "BaZi request is marked computed but no chart exists.", id=req_id)
            payload = chart.get("detail_payload")
            resp = {
                "request": existing_req,
                "chart": {
                    "id": chart.get("id"),
                    "bazi_text": chart.get("bazi_text"),
                    "year_pillar": chart.get("year_pillar"),
                    "month_pillar": chart.get("month_pillar"),
                    "day_pillar": chart.get("day_pillar"),
                    "hour_pillar": chart.get("hour_pillar"),
                    "computed_at": chart.get("computed_at"),
                    "status": chart.get("status"),
                },
                "detail": payload
            }
            _audit("ok", None)
            return resp

        if existing_req.get("status") == "failed":
            _audit("ok", None)
            return {
                "request": existing_req,
                "chart": None,
                "detail": None
            }

        # queued: return request envelope, no detail yet
        _audit("ok", None)
        return {
            "request": existing_req,
            "chart": None,
            "detail": None
        }

    except Exception as e:
        _audit("error", "INTERNAL")
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def getSolarTimes(bazi, **_extra):
    import json, os, datetime, time, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0313000" if __import__("os").path.isdir("./environment_mix/0313000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _new_id(prefix):
        h = hashlib.sha256((prefix + "|" + str(time.time_ns())).encode("utf-8")).hexdigest()[:26]
        return f"{prefix}_{h}"

    def _audit(status_s, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        rows = _load("service_audit.json")
        if not isinstance(rows, list):
            rows = []
        rows.append({
            "id": _new_id("audit"),
            "endpoint": "getSolarTimes",
            "status": status_s,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": datetime.datetime.now(datetime.timezone.utc).isoformat()
        })
        _save("service_audit.json", rows)

    def _rate_limited():
        rows = _load("service_audit.json")
        if not isinstance(rows, list):
            return False
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        c = 0
        for r in rows:
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts)
            except ValueError:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= cutoff:
                c += 1
        return c >= 120

    def _parse_ymdhms(s):
        try:
            return datetime.datetime.strptime(s, "%Y-%m-%d %H:%M:%S")
        except Exception:
            return None

    try:
        if _rate_limited():
            _audit("error", "RATE_LIMIT")
            return _err("RATE_LIMIT", "Too many requests; please wait and retry.")

        if not isinstance(bazi, str) or not bazi.strip():
            _audit("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "bazi must be a non-empty string.", bazi=bazi)
        key = bazi.strip()

        # In this datastore, callers may pass an id; resolve if possible, otherwise treat as raw bazi text.
        bazi_text = None
        if re.match(r"^bzreq_[A-Za-z0-9]+$", key):
            charts = _load("bazi_charts.json")
            if not isinstance(charts, list):
                charts = []
            for c in charts:
                if c.get("bazi_request_id") == key:
                    bazi_text = c.get("bazi_text")
                    break
        elif re.match(r"^bzchart_[A-Za-z0-9]+$", key):
            charts = _load("bazi_charts.json")
            if not isinstance(charts, list):
                charts = []
            for c in charts:
                if c.get("id") == key:
                    bazi_text = c.get("bazi_text")
                    break
        else:
            bazi_text = key

        if not isinstance(bazi_text, str) or not bazi_text.strip():
            _audit("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "bazi could not be resolved to a valid bazi text.", bazi=bazi)

        # Validate format: exactly 4 whitespace-separated tokens
        parts = bazi_text.strip().split()
        if len(parts) != 4 or any(not p for p in parts):
            _audit("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "bazi format is invalid; expected four pillars separated by spaces.", bazi=bazi_text)

        rows = _load("bazi_reverse_solar_times.json")
        if not isinstance(rows, list):
            rows = []

        candidates = [r for r in rows if r.get("bazi_text") == bazi_text and r.get("status") == "active"]

        # Sort: confidence desc then time asc (using utc if present else parsed local text)
        def _sort_key(r):
            conf = r.get("confidence")
            try:
                conf_v = float(conf)
            except Exception:
                conf_v = -1.0
            dt = None
            utc = r.get("solar_datetime_utc")
            if isinstance(utc, str) and utc:
                try:
                    dt = datetime.datetime.fromisoformat(utc)
                except ValueError:
                    dt = None
            if dt is None:
                dt = _parse_ymdhms(r.get("solar_datetime_text") or "")
            if dt is None:
                dt = datetime.datetime.max
            return (-conf_v, dt)

        candidates.sort(key=_sort_key)

        # Real service in description says NOT_FOUND when none exist.
        if not candidates:
            _audit("ok", None)
            return {"bazi": bazi_text, "solarTimes": []}

        _audit("ok", None)
        return {
            "bazi": bazi_text,
            "solarTimes": [
                {
                    "id": r.get("id"),
                    "solarDatetime": r.get("solar_datetime_text"),
                    "defaultTimezone": r.get("default_timezone"),
                    "confidence": r.get("confidence"),
                    "source": r.get("source"),
                    "status": r.get("status")
                } for r in candidates
            ]
        }

    except Exception as e:
        _audit("error", "INTERNAL")
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def getChineseCalendar(solarDatetime=None, **_extra):
    import json, os, datetime, time, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0313000" if __import__("os").path.isdir("./environment_mix/0313000") else "/app/database")
    def _load(n):
