    t0 = time.time()

    def _new_id(prefix):
        h = hashlib.sha256((prefix + "|" + str(time.time_ns())).encode("utf-8")).hexdigest()[:26]
        return f"{prefix}_{h}"

    def _audit(status_s, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        rows = _load("service_audit.json")
        if not isinstance(rows, list):
            rows = []
        rows.append({
            "id": _new_id("audit"),
            "endpoint": "getChineseCalendar",
            "status": status_s,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": datetime.datetime.now(datetime.timezone.utc).isoformat()
        })
        _save("service_audit.json", rows)

    def _rate_limited():
        rows = _load("service_audit.json")
        if not isinstance(rows, list):
            return False
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        c = 0
        for r in rows:
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts)
            except ValueError:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= cutoff:
                c += 1
        return c >= 120

    def _parse_iso_or_resolve_id(s):
        if s is None:
            return None, None, None
        if not isinstance(s, str) or not s.strip():
            raise ValueError("invalid")
        s = s.strip()
        if re.match(r"^(bzreq|calreq)_[A-Za-z0-9]+$", s):
            return "ID", s, None
        dt = datetime.datetime.fromisoformat(s)
        if dt.tzinfo is None or dt.utcoffset() is None:
            raise ValueError("missing tz")
        return "ISO", s, dt

    try:
        if _rate_limited():
            _audit("error", "RATE_LIMIT")
            return _err("RATE_LIMIT", "Too many requests; please wait and retry.")

        default_tz = "Asia/Shanghai"

        kind, raw, dt = None, None, None
        if solarDatetime is not None:
            try:
                kind, raw, dt = _parse_iso_or_resolve_id(solarDatetime)
            except Exception:
                _audit("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "solarDatetime format is invalid; expected ISO-8601 with timezone offset.", solarDatetime=solarDatetime)

        # Determine effective_solar_date
        if solarDatetime is None:
            # today in default timezone (approx via fixed +08:00)
            tz = datetime.timezone(datetime.timedelta(hours=8))
            now_local = datetime.datetime.now(tz)
            effective_date = now_local.date().isoformat()
            solar_iso_store = None
        elif kind == "ISO":
            effective_date = dt.date().isoformat()
            solar_iso_store = raw
        else:
            # ID: try resolve via calendar_requests or bazi_requests if possible; otherwise allow and default to today
            solar_iso_store = raw
            calreqs = _load("calendar_requests.json")
            if not isinstance(calreqs, list):
                calreqs = []
            found = None
            for r in calreqs:
                if r.get("id") == raw:
                    found = r
                    break
            if found and isinstance(found.get("effective_solar_date"), str):
                effective_date = found.get("effective_solar_date")
            else:
                bzreqs = _load("bazi_requests.json")
                if not isinstance(bzreqs, list):
                    bzreqs = []
                bzr = None
                for r in bzreqs:
                    if r.get("id") == raw:
                        bzr = r
                        break
                if bzr and isinstance(bzr.get("normalized_solar_datetime_utc"), str):
                    try:
                        utc_dt = datetime.datetime.fromisoformat(bzr["normalized_solar_datetime_utc"])
                        effective_date = utc_dt.date().isoformat()
                    except ValueError:
                        effective_date = datetime.datetime.now(datetime.timezone.utc).date().isoformat()
                else:
                    tz = datetime.timezone(datetime.timedelta(hours=8))
                    effective_date = datetime.datetime.now(tz).date().isoformat()

        # Persist calendar_requests row (unique by (solar_datetime_iso, default_timezone, effective_solar_date))
        now = datetime.datetime.now(datetime.timezone.utc).isoformat()
        reqs = _load("calendar_requests.json")
        if not isinstance(reqs, list):
            reqs = []
        existing = None
        for r in reqs:
            if (r.get("solar_datetime_iso") or "") == (solar_iso_store or "") and r.get("default_timezone") == default_tz and r.get("effective_solar_date") == effective_date:
                existing = r
                break
        if existing is None:
            req_row = {
                "id": _new_id("calreq"),
                "solar_datetime_iso": solar_iso_store,
                "effective_solar_date": effective_date,
                "default_timezone": default_tz,
                "status": "queued",
                "error_code": None,
                "error_message": None,
                "created_at": now,
                "updated_at": now
            }
            reqs.append(req_row)
            _save("calendar_requests.json", reqs)
            existing = req_row

        # Try return active calendar_days for that date/tz
        days = _load("calendar_days.json")
        if not isinstance(days, list):
            days = []
        day = None
        for d in days:
            if d.get("effective_solar_date") == effective_date and d.get("default_timezone") == default_tz and d.get("status") == "active":
                day = d
                break

        if not day:
            _audit("ok", None)
            return {"request": existing, "day": None, "huangli": None}

        _audit("ok", None)
        return {"request": existing, "day": day, "huangli": day.get("huangli_payload")}

    except Exception as e:
        _audit("error", "INTERNAL")
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def buildBaziFromLunarDatetime(lunarDatetime, gender, eightCharProviderSect=None, **_extra):
    import json, os, datetime, time, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0313000" if __import__("os").path.isdir("./environment_mix/0313000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_iso = datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _new_id(prefix):
        h = hashlib.sha256((prefix + "|" + now_iso + "|" + str(time.time_ns())).encode("utf-8")).hexdigest()[:26]
        return f"{prefix}_{h}"

    def _record_audit(endpoint, status, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        rows = _load("service_audit.json")
        if not isinstance(rows, list):
            rows = []
        rows.append({
            "id": _new_id("audit"),
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": datetime.datetime.now(datetime.timezone.utc).isoformat()
        })
        _save("service_audit.json", rows)
        return latency_ms

    def _rate_limited():
        rows = _load("service_audit.json")
        if not isinstance(rows, list):
            return False
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        c = 0
        for r in rows:
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts)
            except ValueError:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= cutoff:
                c += 1
        return c >= 120

    try:
        if _rate_limited():
            _record_audit("buildBaziFromLunarDatetime", "error", "RATE_LIMIT")
            return _err("RATE_LIMIT", "Too many requests; please wait and retry.")

        if not isinstance(lunarDatetime, str) or not lunarDatetime.strip():
            _record_audit("buildBaziFromLunarDatetime", "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "lunarDatetime is required.")
        token = lunarDatetime.strip()

        if isinstance(gender, bool) or not isinstance(gender, (int, float)) or int(gender) != gender:
            _record_audit("buildBaziFromLunarDatetime", "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "gender must be 0 or 1.")
        gender_i = int(gender)
        if gender_i not in (0, 1):
            _record_audit("buildBaziFromLunarDatetime", "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "gender must be 0 or 1.")

        if eightCharProviderSect is None:
            sect_i = 2
        else:
            if isinstance(eightCharProviderSect, bool) or not isinstance(eightCharProviderSect, (int, float)) or int(eightCharProviderSect) != eightCharProviderSect:
                _record_audit("buildBaziFromLunarDatetime", "error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "eightCharProviderSect must be 1 or 2.")
            sect_i = int(eightCharProviderSect)
            if sect_i not in (1, 2):
                _record_audit("buildBaziFromLunarDatetime", "error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "eightCharProviderSect must be 1 or 2.")

        reqs = _load("bazi_requests.json")
        charts = _load("bazi_charts.json")
