def listBaziRequests(status=None, inputCalendarType=None, requestSource=None, solarDatetimeFrom=None, solarDatetimeTo=None, createdAtFrom=None, createdAtTo=None, page=None, pageSize=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0313000" if __import__("os").path.isdir("./environment_mix/0313000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = time.time()

    if status is not None and status not in ("queued", "computed", "failed"):
        return _err("VALIDATION_ERROR", "status must be one of queued, computed, failed.")
    if inputCalendarType is not None and inputCalendarType not in ("solar", "lunar"):
        return _err("VALIDATION_ERROR", "inputCalendarType must be one of solar, lunar.")
    if requestSource is not None and not isinstance(requestSource, str):
        return _err("VALIDATION_ERROR", "requestSource must be a string.")
    if page is None:
        page = 1
    if pageSize is None:
        pageSize = 20
    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1.")
    if not isinstance(pageSize, int) or pageSize < 1 or pageSize > 200:
        return _err("VALIDATION_ERROR", "pageSize must be an integer between 1 and 200.")

    def _parse_iso(s, allow_tz_optional=True):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            raise ValueError("empty")
        dt = datetime.datetime.fromisoformat(s)
        if dt.tzinfo is None and not allow_tz_optional:
            raise ValueError("tz_required")
        return dt

    try:
        solar_from = _parse_iso(solarDatetimeFrom, allow_tz_optional=False)
        solar_to = _parse_iso(solarDatetimeTo, allow_tz_optional=False)
        created_from = _parse_iso(createdAtFrom, allow_tz_optional=True)
        created_to = _parse_iso(createdAtTo, allow_tz_optional=True)
    except ValueError:
        return _err("VALIDATION_ERROR", "Datetime filter parameters must be valid ISO-8601 strings (solarDatetime* must include timezone).")

    rows = _load("bazi_requests.json")

    def _in_range_iso(row_val, lo_dt, hi_dt, require_tz):
        if lo_dt is None and hi_dt is None:
            return True
        if row_val is None:
            return False
        try:
            dt = datetime.datetime.fromisoformat(row_val)
        except ValueError:
            return False
        if require_tz and dt.tzinfo is None:
            return False
        if lo_dt is not None and dt < lo_dt:
            return False
        if hi_dt is not None and dt > hi_dt:
            return False
        return True

    def _in_range_created(row_val, lo_dt, hi_dt):
        if lo_dt is None and hi_dt is None:
            return True
        if row_val is None:
            return False
        try:
            dt = datetime.datetime.fromisoformat(row_val)
        except ValueError:
            return False
        if lo_dt is not None:
            # If filter has tz, compare in UTC when possible
            if lo_dt.tzinfo and dt.tzinfo:
                if dt.astimezone(datetime.timezone.utc) < lo_dt.astimezone(datetime.timezone.utc):
                    return False
            else:
                if dt < lo_dt:
                    return False
        if hi_dt is not None:
            if hi_dt.tzinfo and dt.tzinfo:
                if dt.astimezone(datetime.timezone.utc) > hi_dt.astimezone(datetime.timezone.utc):
                    return False
            else:
                if dt > hi_dt:
                    return False
        return True

    filtered = []
    for r in rows:
        if status is not None and r.get("status") != status:
            continue
        if inputCalendarType is not None and r.get("input_calendar_type") != inputCalendarType:
            continue
        if requestSource is not None and r.get("request_source") != requestSource:
            continue
        if not _in_range_iso(r.get("solar_datetime_iso"), solar_from, solar_to, require_tz=True):
            continue
        if not _in_range_created(r.get("created_at"), created_from, created_to):
            continue
        filtered.append(r)

    # Order by created_at desc (fallback to id)
    def _created_key(r):
        v = r.get("created_at")
        try:
            return datetime.datetime.fromisoformat(v) if isinstance(v, str) else datetime.datetime.min
        except ValueError:
            return datetime.datetime.min

    filtered.sort(key=lambda r: (_created_key(r), r.get("id") or ""), reverse=True)

    total = len(filtered)
    start = (page - 1) * pageSize
    end = start + pageSize
    page_rows = filtered[start:end]
    has_more = end < total

    return {
        "data": page_rows,
        "page": page,
        "page_size": pageSize,
        "total": total,
        "has_more": has_more,
        "latency_ms": int((time.time() - started) * 1000)
    }

