        for r in rows:
            if r.get("id") == rid:
                row = r
                break

        if not row:
            _audit("error", "NOT_FOUND")
            return _err("NOT_FOUND", "calendar request not found", id=rid)

        _audit("ok", None)
        return {"calendar_request": row}

    except Exception as e:
        _audit("error", "INTERNAL")
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def deprecateReverseSolarTime(id, status, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0313000" if __import__("os").path.isdir("./environment_mix/0313000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _new_id(prefix):
        h = hashlib.sha256((prefix + "|" + str(time.time_ns())).encode("utf-8")).hexdigest()[:26]
        return f"{prefix}_{h}"

    def _audit(status_s, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        rows = _load("service_audit.json")
        if not isinstance(rows, list):
            rows = []
        rows.append({
            "id": _new_id("audit"),
            "endpoint": "deprecateReverseSolarTime",
            "status": status_s,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "timestamp": datetime.datetime.now(datetime.timezone.utc).isoformat()
        })
        _save("service_audit.json", rows)

    def _rate_limited():
        rows = _load("service_audit.json")
        if not isinstance(rows, list):
            return False
        cutoff = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(seconds=60)
        c = 0
        for r in rows:
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts)
            except ValueError:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= cutoff:
                c += 1
        return c >= 120

    try:
        if _rate_limited():
            _audit("error", "RATE_LIMIT")
            return _err("RATE_LIMIT", "Too many requests; please wait and retry.")

        if not isinstance(id, str) or not id.strip():
            _audit("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "id must be a non-empty string", id=id)
        if status != "deprecated":
            _audit("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be 'deprecated'.", status=status)

        rid = id.strip()

        rows = _load("bazi_reverse_solar_times.json")
        if not isinstance(rows, list):
            rows = []

        target = None
        for r in rows:
            if r.get("id") == rid:
                target = r
                break

        # In this environment, callers sometimes pass bzreq_ ids; try resolve to first active reverse time for that request's bazi_text.
        if target is None and rid.startswith("bzreq_"):
            charts = _load("bazi_charts.json")
            if not isinstance(charts, list):
                charts = []
            bazi_text = None
            for c in charts:
                if c.get("bazi_request_id") == rid:
                    bazi_text = c.get("bazi_text")
                    break
            if bazi_text:
                for r in rows:
                    if r.get("bazi_text") == bazi_text and r.get("status") == "active":
                        target = r
                        break

        if target is None:
            _audit("error", "NOT_FOUND")
            return _err("NOT_FOUND", "reverse solar time not found", id=rid)

        cur = target.get("status")
        if cur == "deprecated":
            # idempotent
            _audit("ok", None)
            return {"reverse_solar_time": target}

        if cur != "active":
            _audit("error", "CONFLICT")
            return _err("CONFLICT", "Only status transition active -> deprecated is allowed.", id=target.get("id"), current_status=cur)

        target["status"] = "deprecated"
        target["updated_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat()
        _save("bazi_reverse_solar_times.json", rows)

        _audit("ok", None)
        return {"reverse_solar_time": target}

    except Exception as e:
        _audit("error", "INTERNAL")
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))
